"""Student pack for Lab 2 (8 A4 pages, Greek) -> out/Lab2_pack.html ; every number comes from numbers.json. CSS is taken from the Lab 1 pack (not executed, only read)."""
import json, os, html, re
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(f'{HERE}/numbers.json', encoding='utf8'))
CSS = re.search(r"CSS = '''(.*?)'''", open(f'{HERE}/../lab1/build_pack.py', encoding='utf8').read(), re.S).group(1)
CSS += '.t td.r,.t th.r{text-align:right;font-variant-numeric:tabular-nums}.t tr.sep td{border-top:1.2pt solid var(--ink)}.t td.g{color:var(--muted)}.real{background:#E6F4EC;border-left:3mm solid var(--green);border-radius:3mm;padding:3.5mm 5mm;margin:4mm 0;font-size:10.5pt;line-height:1.45}.msg{min-height:40mm}.t.sub td{padding-top:1.1mm;padding-bottom:1.1mm}'
pc = lambda v: f'{round(100 * v)}%'; e = html.escape; gr = lambda v, d=2: f'{v:.{d}f}'.replace('.', ',').replace('-', '−'); th = lambda n: f'{n:,}'.replace(',', '.')
D = N['data']; M = N['moments']; T = N['test']; S = N['sweep']; K = N['topk']; G = N['groups']; NZ = N['nonzero_approved_test']; ZA = N['zero_approved_test']
FOOT = 'Πραγματικά δεδομένα · Realinho et al. (2022), UCI 697 · CC BY 4.0'
def bars(items, unit='%', H=110, vmax=None):
    mx = (vmax or 1) if unit == '%' else max(i['v'] for i in items); o = ['<div class="barrow">']
    for i in items:
        h = max(2, round(i['v'] / mx * H)); val = pc(i['v']) if unit == '%' else th(i['v'])
        o.append(f'<div class="bar"><span class="bv">{val}</span><i class="t-{i.get("tone", "blue")}" style="height:{h}px"></i><span class="bl">{e(i["l"])}</span>' + (f'<span class="bn">n = {i["n"]}</span>' if 'n' in i else '') + '</div>')
    return ''.join(o) + '</div>'
def fig(title, inner, note=''): return f'<div class="fig"><h3>{e(title)}</h3>{inner}' + (f'<p class="fnote">{note}</p>' if note else '') + '</div>'
def page(n, kicker, title, body): return f'<section class="page"><header><span class="kick">{e(kicker)}</span><h1>{e(title)}</h1></header><div class="content">{body}</div><footer><span>{e(FOOT)}</span><span>Εργαστήριο 2 · σελίδα {n} από 8</span></footer></section>'
def ask(items): return '<div class="ask"><h3>Ερωτήματα για την ομάδα</h3><ul>' + ''.join(f'<li>{i}</li>' for i in items) + '</ul></div>'
P = []
# ---------- page 1
P.append(f'''<section class="page cover"><p class="course">Βάσεις Δεδομένων &amp; Ανάλυση Δεδομένων Μάθησης · Εβδομάδα 3, Μέρος 2</p>
<p class="kick">Εργαστήριο 2 · Πακέτο τεκμηρίων</p><h1 class="big">Ποιοι φοιτητές θα λάβουν τι;</h1>
<div class="real"><b>Τα δεδομένα αυτού του πακέτου είναι πραγματικά και ανωνυμοποιημένα.</b> Αφορούν {th(D["n"])} φοιτητές {D["n_courses"]} προπτυχιακών προγραμμάτων του Πολυτεχνικού Ινστιτούτου του Portalegre, στην Πορτογαλία. Δημοσιεύθηκαν από τους Realinho, Machado, Baptista και Martins (2022) στο περιοδικό <i>Data</i>, 7(11), 146, και διατίθενται από το UCI Machine Learning Repository (σύνολο δεδομένων 697) με άδεια CC BY 4.0. Οι δημιουργοί ζητούν να αναφέρεται επίσης η εργασία των Martins, Tolledo, Machado, Baptista και Realinho (2021).</div>
<h2>Η υπόθεση</h2><p>Το ίδρυμα διαθέτει εργαλείο που δίνει στην ομάδα υποστήριξης των φοιτητών μια εκτίμηση του κινδύνου εγκατάλειψης. Η εκτίμηση γίνεται στο <b>τέλος του 1ου εξαμήνου</b>. Έστω ότι η ομάδα υποστήριξης μπορεί να δει προσωπικά <b>έως 100 φοιτητές</b>. Το μοντέλο είναι έτοιμο και δεν αλλάζει. Εσείς αποφασίζετε πώς θα χρησιμοποιηθεί.</p>
<h2>Το ζητούμενο</h2><ol class="num"><li><span><b>Α. Η ενέργεια</b> που επιλέγετε, και το κατώφλι που της αντιστοιχεί. Πρώτα η ενέργεια, μετά το κατώφλι.</span></li><li><span><b>Β. Η υποομάδα</b> που ο κανόνας σας μεταχειρίζεται χειρότερα: ποιο είδος αδικίας είναι, και τι κάνετε γι' αυτό.</span></li><li><span><b>Γ. Το μήνυμα</b> προς έναν φοιτητή που επισημάνθηκε, έως 60 λέξεις, γραμμένο ολόκληρο.</span></li></ol>
<h2>Πώς δουλεύετε</h2><p>Ορίζετε συντονιστή, που κρατά τον χρόνο, και εισηγητή, που θα διαβάσει το φύλλο απάντησης. Όλοι διαβάζουν τις σελίδες 1 έως 3· τα Τεκμήρια 3, 4 και 5 μοιράζονται, ένα ανά άτομο. Δεν γράφετε κώδικα.</p>
<h2>Περιεχόμενα</h2><table class="toc"><tr><td>Τεκμήριο 1</td><td>Τα δεδομένα, και πότε προβλέπουμε</td><td>σελ. 2</td></tr><tr><td>Τεκμήριο 2</td><td>Το κατώφλι</td><td>σελ. 3</td></tr><tr><td>Τεκμήριο 3</td><td>Η δυναμικότητα: ποιοι βρίσκονται στην κορυφή της λίστας</td><td>σελ. 4</td></tr><tr><td>Τεκμήριο 4</td><td>Οι υποομάδες</td><td>σελ. 5</td></tr><tr><td>Τεκμήριο 5</td><td>Τι βαραίνει στο μοντέλο</td><td>σελ. 6</td></tr><tr><td>Υπενθύμιση</td><td>Τα τρία εργαλεία του Μέρους 1</td><td>σελ. 7</td></tr><tr><td>Απάντηση</td><td>Φύλλο απάντησης, ένα ανά αίθουσα</td><td>σελ. 8</td></tr></table>
<footer><span>{e(FOOT)}</span><span>Εργαστήριο 2 · σελίδα 1 από 8</span></footer></section>''')
